//! Morning Brief assembly (§6.8 / FR-MB-01..06). The prose ("What happened", the polished
//! wording) is generated by the Batch API in the Dream Cycle's final job — but *which* items go in
//! *which* section, *in what order*, *capped where*, and *how confidence is marked* is pure,
//! deterministic assembly, tested here without a network.
//!
//! Rules encoded:
//! - Sections and their sources (FR-MB-01): Today (calendar, time-ordered) · Commitments due
//!   (overdue or due within 7 days, ≤4 undated) · Open loops (top-5, freshest activity first) ·
//!   What happened (≤5 lines) · Suggested actions (≤3, each
//!   L2/L3-tagged via [`ActionCandidate`]).
//! - Confidence (FR-MB-05, via [`crate::confidence`]): Low (<0.5) state is **excluded** — never
//!   shown as a morning fact; Medium (0.5..<0.8) is flagged `possibly` for the UI to distinguish;
//!   High passes through. Provenance travels with every item.
//! - Degraded brief (FR-MB-04): when generation failed, show local-only data (calendar + overdue
//!   commitments), no LLM prose, no suggestions — never an empty/error screen at 8am.

use crate::assemble::ActionCandidate;
use crate::confidence::{band, Band};

/// Max open loops shown (FR-MB-01: top-5).
pub const OPEN_LOOPS_MAX: usize = 5;
/// Max commitments shown (daily summaries design §3.2).
pub const COMMITMENTS_MAX: usize = 5;
/// Dated commitments show once due within this many days (overdue ones always qualify).
const DUE_SOON_DAYS: i64 = 7;
/// Overdue by more than this many days = stale: listed after the fresh ones.
const STALE_OVERDUE_DAYS: i64 = 14;
/// Undated commitments shown at most this many.
const UNDATED_MAX: usize = 4;
/// Max suggested actions (FR-MB-01: ≤3).
pub const SUGGESTED_ACTIONS_MAX: usize = 3;
/// Max "What happened" lines (FR-MB-01: 3–5 lines; assembly caps the upper bound).
pub const WHAT_HAPPENED_MAX: usize = 5;

/// A calendar entry for Today (FR-MB-01). Meeting Prep is offered for every entry.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CalendarLine {
    pub start_ms: i64,
    pub title: String,
    /// A date, not an instant (`start_ms` is 00:00 UTC of that date): shown without a time.
    pub all_day: bool,
    /// FR-MB-06: changed after the brief was generated (shown with an "Updated" mark).
    pub updated: bool,
}

/// A commitment for the "Commitments due" section (today-due or overdue).
#[derive(Debug, Clone)]
pub struct CommitmentDue {
    pub description: String,
    pub due_at_ms: Option<i64>,
    pub overdue: bool,
    /// Whole days from now to `due_at_ms` (negative = overdue). `None` when undated.
    pub days_until_due: Option<i64>,
    pub confidence: f64,
    /// None denotes edited context, not a source-backed claim.
    pub provenance_event_id: Option<i64>,
}

impl CommitmentDue {
    /// [`Self::days_until_due`] for a due time seen from `now_ms` (floor, so 2h ago is -1).
    pub fn days_until(due_ms: i64, now_ms: i64) -> i64 {
        due_ms.saturating_sub(now_ms).div_euclid(86_400_000)
    }
}

/// An open loop for the "Open loops" section.
#[derive(Debug, Clone)]
pub struct OpenLoopItem {
    pub description: String,
    pub staleness_days: u32,
    pub confidence: f64,
    pub provenance_event_id: Option<i64>,
}

/// One rendered brief line, with provenance and the `possibly` (medium-confidence) marker.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BriefItem {
    pub text: String,
    pub provenance_event_id: Option<i64>,
    /// FR-MB-05: medium-confidence (0.5..<0.8) items are flagged so the UI can mark them "possibly".
    pub possibly: bool,
}

/// The assembled Morning Brief.
#[derive(Debug, Clone)]
pub struct MorningBrief {
    pub today: Vec<CalendarLine>,
    pub commitments_due: Vec<BriefItem>,
    pub open_loops: Vec<BriefItem>,
    /// Yesterday's summary (3–5 lines). Empty in a degraded brief.
    pub what_happened: Vec<String>,
    /// ≤3 suggested actions, each already L2/L3-tagged. Empty in a degraded brief.
    pub suggested_actions: Vec<ActionCandidate>,
    /// FR-MB-04: true when this is the local-only fallback (no LLM prose).
    pub degraded: bool,
}

/// Render one confidence-bearing item, or `None` when it is Low (excluded, FR-MB-05/FR-ST-20).
fn to_item(text: &str, confidence: f64, provenance_event_id: Option<i64>) -> Option<BriefItem> {
    match band(confidence) {
        Band::Low => None,
        b => Some(BriefItem {
            text: text.to_string(),
            provenance_event_id,
            possibly: b == Band::Medium,
        }),
    }
}

/// Order today's calendar by start time (FR-MB-01: time-ordered), all-day entries first: their
/// `start_ms` is a UTC midnight, not a local time, so it cannot be interleaved with timed ones.
fn ordered_today(mut calendar: Vec<CalendarLine>) -> Vec<CalendarLine> {
    calendar.sort_by_key(|c| (!c.all_day, c.start_ms));
    calendar
}

pub(crate) fn normalized_line(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ").to_lowercase()
}

fn canonical_highlight(text: &str) -> String {
    let normalized = normalized_line(text);
    normalized
        .split_once(':')
        .filter(|(prefix, _)| {
            prefix
                .split_whitespace()
                .last()
                .is_some_and(|word| matches!(word, "responded" | "said" | "wrote"))
        })
        .map_or(normalized.clone(), |(_, body)| body.trim().to_string())
}

/// Whether two brief lines carry the same useful text despite a short speaker-attribution prefix.
pub fn equivalent_lines(a: &str, b: &str) -> bool {
    let (a, b) = (canonical_highlight(a), canonical_highlight(b));
    a == b
}

pub(crate) fn unique_lines(items: impl IntoIterator<Item = BriefItem>, limit: usize) -> Vec<BriefItem> {
    let mut out = Vec::new();
    for item in items {
        if !out
            .iter()
            .any(|kept: &BriefItem| normalized_line(&kept.text) == normalized_line(&item.text))
        {
            out.push(item);
            if out.len() == limit {
                break;
            }
        }
    }
    out
}

/// Commitments worth a morning line: overdue or due within [`DUE_SOON_DAYS`], plus at most
/// [`UNDATED_MAX`] undated. Recently overdue first (nearest to now), then what is due next,
/// long-stale overdue after them, undated last — a month-old overdue item must not crowd out
/// today's.
fn ordered_commitments(commitments: &[CommitmentDue]) -> Vec<BriefItem> {
    // (group, upcoming-after-overdue, distance from today) — lower sorts earlier.
    let rank = |c: &CommitmentDue| match c.days_until_due {
        Some(d) if d < -STALE_OVERDUE_DAYS => (1, 0, -d),
        Some(d) => (0, i64::from(!c.overdue), d.abs()),
        None => (2, 0, 0),
    };
    let mut undated = 0;
    let mut kept: Vec<(&CommitmentDue, BriefItem)> = commitments
        .iter()
        .filter(|c| c.days_until_due.is_none_or(|d| d <= DUE_SOON_DAYS))
        .filter_map(|c| to_item(&c.description, c.confidence, c.provenance_event_id).map(|i| (c, i)))
        .collect();
    kept.sort_by_key(|(c, _)| (rank(c), c.due_at_ms.unwrap_or(i64::MAX)));
    kept.retain(|(c, _)| {
        c.days_until_due.is_some() || {
            undated += 1;
            undated <= UNDATED_MAX
        }
    });
    unique_lines(kept.into_iter().map(|(_, i)| i), COMMITMENTS_MAX)
}

/// Open loops by recent activity (freshest first), capped at [`OPEN_LOOPS_MAX`]; Low-confidence
/// excluded. A loop untouched for weeks sorts last rather than leading the morning.
fn top_open_loops(open_loops: &[OpenLoopItem]) -> Vec<BriefItem> {
    let mut kept: Vec<(&OpenLoopItem, BriefItem)> = open_loops
        .iter()
        .filter_map(|o| to_item(&o.description, o.confidence, o.provenance_event_id).map(|i| (o, i)))
        .collect();
    kept.sort_by_key(|(b, _)| b.staleness_days);
    unique_lines(kept.into_iter().map(|(_, i)| i), OPEN_LOOPS_MAX)
}

/// Assemble the full Morning Brief (FR-MB-01). Suggested actions are taken pre-ranked from
/// Fusion / Follow-up Sentinel and capped at [`SUGGESTED_ACTIONS_MAX`]; "What happened" is capped
/// at [`WHAT_HAPPENED_MAX`] lines.
pub fn assemble_brief(
    calendar: Vec<CalendarLine>,
    commitments: &[CommitmentDue],
    open_loops: &[OpenLoopItem],
    what_happened: Vec<String>,
    suggested: Vec<ActionCandidate>,
) -> MorningBrief {
    let mut what = what_happened;
    what.truncate(WHAT_HAPPENED_MAX);
    let mut actions = suggested;
    actions.truncate(SUGGESTED_ACTIONS_MAX);
    MorningBrief {
        today: ordered_today(calendar),
        commitments_due: ordered_commitments(commitments),
        open_loops: top_open_loops(open_loops),
        what_happened: what,
        suggested_actions: actions,
        degraded: false,
    }
}

/// Assemble the degraded, local-only brief (FR-MB-04): calendar + overdue commitments only, no LLM
/// prose, no suggestions. Shown when Dream Cycle / Batch generation failed so the morning is never
/// an empty or error screen.
pub fn assemble_degraded(calendar: Vec<CalendarLine>, commitments: &[CommitmentDue]) -> MorningBrief {
    // Only overdue commitments in the fallback — the local, unambiguous ones.
    let overdue: Vec<CommitmentDue> = commitments.iter().filter(|c| c.overdue).cloned().collect();
    MorningBrief {
        today: ordered_today(calendar),
        commitments_due: ordered_commitments(&overdue),
        open_loops: Vec::new(),
        what_happened: Vec::new(),
        suggested_actions: Vec::new(),
        degraded: true,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn commitment(
        desc: &str,
        due: Option<i64>,
        overdue: bool,
        conf: f64,
        ev: i64,
    ) -> CommitmentDue {
        CommitmentDue {
            description: desc.into(),
            due_at_ms: due,
            overdue,
            days_until_due: due.map(|_| if overdue { -1 } else { 0 }),
            confidence: conf,
            provenance_event_id: Some(ev),
        }
    }
    fn dated(desc: &str, days: i64) -> CommitmentDue {
        CommitmentDue {
            days_until_due: Some(days),
            ..commitment(desc, Some(days), days < 0, 0.9, 1)
        }
    }
    fn loop_item(desc: &str, staleness: u32, conf: f64, ev: i64) -> OpenLoopItem {
        OpenLoopItem {
            description: desc.into(),
            staleness_days: staleness,
            confidence: conf,
            provenance_event_id: Some(ev),
        }
    }
    fn cal(start: i64, title: &str) -> CalendarLine {
        CalendarLine { start_ms: start, title: title.into(), all_day: false, updated: false }
    }

    #[test]
    fn today_is_time_ordered() {
        let brief = assemble_brief(
            vec![cal(300, "late"), cal(100, "early"), cal(200, "mid")],
            &[],
            &[],
            vec![],
            vec![],
        );
        let titles: Vec<&str> = brief.today.iter().map(|c| c.title.as_str()).collect();
        assert_eq!(titles, vec!["early", "mid", "late"]);
    }

    #[test]
    fn low_confidence_commitments_and_loops_are_excluded() {
        let brief = assemble_brief(
            vec![],
            &[commitment("shaky", Some(10), false, 0.3, 1), commitment("solid", Some(10), false, 0.9, 2)],
            &[loop_item("shaky loop", 9, 0.4, 3), loop_item("real loop", 9, 0.85, 4)],
            vec![],
            vec![],
        );
        assert_eq!(brief.commitments_due.len(), 1);
        assert_eq!(brief.commitments_due[0].text, "solid");
        assert_eq!(brief.open_loops.len(), 1);
        assert_eq!(brief.open_loops[0].text, "real loop");
    }

    #[test]
    fn medium_confidence_items_are_flagged_possibly() {
        let brief = assemble_brief(
            vec![],
            &[commitment("maybe due", Some(10), false, 0.6, 1), commitment("certain", Some(10), false, 0.95, 2)],
            &[],
            vec![],
            vec![],
        );
        let maybe = brief.commitments_due.iter().find(|i| i.text == "maybe due").unwrap();
        let certain = brief.commitments_due.iter().find(|i| i.text == "certain").unwrap();
        assert!(maybe.possibly, "0.6 confidence must be flagged possibly");
        assert!(!certain.possibly, "0.95 confidence must not be flagged");
    }

    #[test]
    fn commitments_show_only_the_near_window_recent_overdue_first_stale_after() {
        let brief = assemble_brief(
            vec![],
            &[
                dated("far future", 10),
                dated("stale", -30),
                dated("due soon", 1),
                dated("overdue 3d", -3),
                dated("overdue 1d", -1),
                dated("not yet", 3),
            ],
            &[],
            vec![],
            vec![],
        );
        let order: Vec<&str> = brief.commitments_due.iter().map(|i| i.text.as_str()).collect();
        assert_eq!(order, vec!["overdue 1d", "overdue 3d", "due soon", "not yet", "stale"]);
    }

    #[test]
    fn at_most_four_undated_commitments_and_they_come_last() {
        let undated = |d: &str| commitment(d, None, false, 0.9, 1);
        let brief = assemble_brief(
            vec![],
            &[undated("u1"), undated("u2"), undated("u3"), dated("due soon", 0)],
            &[],
            vec![],
            vec![],
        );
        let order: Vec<&str> = brief.commitments_due.iter().map(|i| i.text.as_str()).collect();
        assert_eq!(order, vec!["due soon", "u1", "u2", "u3"]);
        let five = ["u1", "u2", "u3", "u4", "u5"].map(undated);
        let brief = assemble_brief(vec![], &five, &[], vec![], vec![]);
        let order: Vec<&str> = brief.commitments_due.iter().map(|i| i.text.as_str()).collect();
        assert_eq!(order, vec!["u1", "u2", "u3", "u4"]);
    }

    #[test]
    fn commitments_are_deduplicated_and_capped_at_five() {
        let brief = assemble_brief(
            vec![],
            &[
                commitment("I'll send the report Friday", Some(1), true, 0.9, 1),
                commitment("  I'LL send   the report Friday ", Some(2), true, 0.9, 2),
                commitment("Review launch notes", Some(3), true, 0.9, 3),
                commitment("Fix the login test", Some(4), true, 0.9, 4),
                commitment("Merge PR #42", Some(5), true, 0.9, 5),
                commitment("Publish release notes", Some(6), true, 0.9, 6),
                commitment("Send invoice", Some(7), true, 0.9, 7),
            ],
            &[],
            vec![],
            vec![],
        );

        assert_eq!(brief.commitments_due.len(), 5);
        assert_eq!(
            brief
                .commitments_due
                .iter()
                .filter(|item| item.text.contains("send the report Friday"))
                .count(),
            1
        );
    }

    #[test]
    fn open_loops_are_top_five_freshest_first() {
        let loops: Vec<OpenLoopItem> =
            (0..8).map(|i| loop_item(&format!("loop{i}"), i as u32, 0.9, i)).collect();
        let brief = assemble_brief(vec![], &[], &loops, vec![], vec![]);
        assert_eq!(brief.open_loops.len(), OPEN_LOOPS_MAX);
        // freshest first: loop0 (staleness 0) … loop4
        assert_eq!(brief.open_loops[0].text, "loop0");
        assert_eq!(brief.open_loops[4].text, "loop4");
    }

    #[test]
    fn open_loops_collapse_exact_whitespace_and_case_variants() {
        let brief = assemble_brief(
            vec![],
            &[],
            &[
                loop_item("Review PR #42", 10, 0.9, 1),
                loop_item("  REVIEW   PR #42 ", 9, 0.9, 2),
                loop_item("Prepare launch notes", 8, 0.9, 3),
            ],
            vec![],
            vec![],
        );

        assert_eq!(brief.open_loops.len(), 2);
    }

    #[test]
    fn open_loops_keep_distinct_qualifiers() {
        let brief = assemble_brief(
            vec![],
            &[],
            &[
                loop_item("Send report Friday", 10, 0.9, 1),
                loop_item("Send report Friday after legal approval", 9, 0.9, 2),
            ],
            vec![],
            vec![],
        );

        assert_eq!(brief.open_loops.len(), 2);
    }

    #[test]
    fn state_dedupe_preserves_owners_and_meaningful_symbols() {
        let brief = assemble_brief(
            vec![],
            &[],
            &[
                loop_item("Maya said: Review C++ migration", 10, 0.9, 1),
                loop_item("Alex said: Review C++ migration", 9, 0.9, 2),
                loop_item("Maya said: Review C# migration", 8, 0.9, 3),
            ],
            vec![],
            vec![],
        );

        assert_eq!(brief.open_loops.len(), 3);
    }

    #[test]
    fn what_happened_and_suggestions_are_capped() {
        let lines: Vec<String> = (0..9).map(|i| format!("line{i}")).collect();
        // build > 3 dummy actions via a simple local action
        use shogun_agents::permission::{Action, LocalAction};
        let mk = |q: &str| {
            ActionCandidate::new(
                Action::Local(LocalAction::LocalSearch { query: q.into() }),
                q,
                crate::assemble::ActionLabel::new(crate::assemble::LabelKey::SearchMemory, q, false),
            )
        };
        let actions = vec![mk("a"), mk("b"), mk("c"), mk("d"), mk("e")];
        let brief = assemble_brief(vec![], &[], &[], lines, actions);
        assert_eq!(brief.what_happened.len(), WHAT_HAPPENED_MAX);
        assert_eq!(brief.suggested_actions.len(), SUGGESTED_ACTIONS_MAX);
    }

    #[test]
    fn degraded_brief_is_local_only_no_prose_or_suggestions() {
        let brief = assemble_degraded(
            vec![cal(100, "standup")],
            &[
                commitment("overdue thing", Some(50), true, 0.9, 1),
                commitment("not overdue", Some(999), false, 0.9, 2),
            ],
        );
        assert!(brief.degraded);
        assert_eq!(brief.today.len(), 1);
        // only the overdue commitment survives the fallback
        assert_eq!(brief.commitments_due.len(), 1);
        assert_eq!(brief.commitments_due[0].text, "overdue thing");
        assert!(brief.what_happened.is_empty());
        assert!(brief.suggested_actions.is_empty());
        assert!(brief.open_loops.is_empty());
    }

    #[test]
    fn provenance_travels_with_every_item() {
        let brief = assemble_brief(
            vec![],
            &[commitment("c", Some(1), false, 0.9, 42)],
            &[loop_item("l", 3, 0.9, 43)],
            vec![],
            vec![],
        );
        assert_eq!(brief.commitments_due[0].provenance_event_id, Some(42));
        assert_eq!(brief.open_loops[0].provenance_event_id, Some(43));
    }
}
